BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_attention_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,night_loss_frequency INTEGER NOT NULL DEFAULT 0,mindless_video_minutes INTEGER NOT NULL DEFAULT 0,sleep_minutes INTEGER,help_requests INTEGER NOT NULL DEFAULT 0,is_minor BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_trigger_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,trigger_category TEXT NOT NULL CHECK(trigger_category IN('time','emotion','place','social','fatigue','other')),intensity INTEGER NOT NULL CHECK(intensity BETWEEN 1 AND 5),context_summary TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_urge_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,urge_category TEXT NOT NULL CHECK(urge_category IN('short_video','gaming','sexual_content','other')),intensity INTEGER NOT NULL CHECK(intensity BETWEEN 1 AND 5),response_used TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_digital_environment_changes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,change_type TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_replacement_habits(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,title TEXT NOT NULL,duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 1 AND 180),completed_count INTEGER NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_relapse_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,category TEXT NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,severity INTEGER NOT NULL CHECK(severity BETWEEN 1 AND 5),specific_content_stored BOOLEAN NOT NULL DEFAULT FALSE,private BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(specific_content_stored=FALSE),CHECK(private=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_recovery_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,relapse_event_id UUID REFERENCES mission_bridge_relapse_events(id),grace_statement TEXT NOT NULL,immediate_environment_change TEXT NOT NULL,replacement_action TEXT NOT NULL,support_request TEXT NOT NULL DEFAULT '',started_at TIMESTAMPTZ NOT NULL DEFAULT now(),recovered_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_mb_attention_assessment_user ON mission_bridge_attention_assessments(tenant_id,user_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_mb_attention_recovery_user ON mission_bridge_recovery_plans(tenant_id,user_id,started_at DESC);
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_attention_assessments','mission_bridge_trigger_logs','mission_bridge_urge_logs','mission_bridge_digital_environment_changes','mission_bridge_replacement_habits','mission_bridge_relapse_events','mission_bridge_recovery_plans'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
UPDATE mission_bridge_program_definitions SET title='注意力重建与真实生活30天',active_version='2.0.0' WHERE id='attention-reset-30';
INSERT INTO mission_bridge_program_versions(program_id,version,definition,safeguarding_profile) VALUES('attention-reset-30','2.0.0','{"durationWeeks":4,"durationDays":30,"sessionMode":"hybrid","voluntary":true,"steps":30,"flow":["触发识别","环境改造","替代行为","每日短操练","同伴守望","失败恢复","身份和价值重建"],"metrics":["夜间失控频率","无意识刷视频时长","睡眠时间","替代习惯完成率","主动求助次数","复发恢复速度"],"successNotBasedOnlyOnStreak":true}'::jsonb,'{"noShame":true,"noPornographicUploads":true,"noSpecificSearchTerms":true,"privateRelapseRecords":true,"noLeaderboards":true,"minorGuardianFlow":true,"professionalReferral":true,"noCoercion":true}'::jsonb) ON CONFLICT DO NOTHING;
COMMIT;
